import Service from "#class/service";
import type { ClaimRij, PolisId } from "#types";

export default class ClaimService extends Service {
    /** Geeft een rij van claim-objects uit Axon voor het gegeven polisnummer met de gegeven criteria */
    async getClaimsData(polisnummer: PolisId) {
        const rawResponse = await this.session.getAxonRaw(
            "claims/search-by-policy/overview",
            {
                policyIdentifier: polisnummer,
                clientIdentifier: this.session._clientId!
            },
            {
                base: "service",
                headers: { accept: "text/event-stream" },
            },
        );
        const rawText = await rawResponse.text()
        return parseClaims(rawText);
    }
}

function parseClaims(text: string) {
    return text
        .split("\n\n")
        .filter(block => block.startsWith("event: message"))
        .map(block => {
            const dataLine = block.split("\n").find(line => line.startsWith("data:"))!;
            return JSON.parse(dataLine.slice(5).trim()).object as ClaimRij;
        })
}